var t=`0414-colcannon`;var i=`world-0414`;var o=`IE`;var a=`northern-europe`;var s=4;var r=41;var l={en:`Colcannon`,ua:`Колканнон`};var d={en:`A traditional dish from Ireland, centered on potato, white cabbage, green onion, whole cow milk. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірландія. Основні складники: картопля, білоголова капуста, зелена цибуля, цільне коров'яче молоко. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,900,`g`],[`water`,1300,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`white-cabbage`,330,`g`],[`green-onion`,100,`g`],[`unsalted-butter`,70,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`whole-cow-milk`,200,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,35,`g`]]}];var u={slug:t,id:i,country:`IE`,region:a,servings:4,minutes:41,title:l,text:d,steps:g};export{o as country,u as default,i as id,r as minutes,a as region,s as servings,t as slug,g as steps,d as text,l as title};